use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut merged_intervals = Vec::new();
    let mut current_interval = (0, 0);

    for item in input.as_array() {
        let start = item[0].as_i64().unwrap();
        let end = item[1].as_i64().unwrap();

        if current_interval.0 <= start && current_interval.1 >= end {
            // Merge overlapping intervals
            current_interval = (current_interval.0.min(start), current_interval.1.max(end));
        } else {
            // Add a new interval
            merged_intervals.push(current_interval);
            current_interval = (start, end);
        }
    }

    // Add the last interval
    merged_intervals.push(current_interval);

    // Find the largest internal uncovered gap
    let mut max_gap = 0;
    for i in 1..merged_intervals.len() {
        let gap = merged_intervals[i].0 - merged_intervals[i - 1].1;
        if gap > max_gap {
            max_gap = gap;
        }
    }

    // Return the result as a JSON value
    serde_json::Value::Object {
        key: "expected".to_string(),
        value: serde_json::Value::Number(max_gap as f64),
    }
}
